public class Main {
    static class Animal {
        String name;
        Animal(String name) { this.name = name; }
        String speak() { return name + " makes a sound"; }
    }

    static class Dog extends Animal {
        Dog(String name) { super(name); }
        @Override String speak() { return name + " barks"; }
    }

    static class Cat extends Animal {
        Cat(String name) { super(name); }
        @Override String speak() { return name + " meows"; }
    }

    public static void main(String[] args) {
        Animal[] pets = { new Dog("Bruno"), new Cat("Milo") };
        for (Animal pet : pets) System.out.println(pet.speak());
    }
}

public class Main {
    static class Employee {
        private final String name;
        Employee(String name) { this.name = name; }
        double pay() { return 30_000; }
        @Override public String toString() { return name + ":" + pay(); }
    }

    static class Manager extends Employee {
        Manager(String name) { super(name); }
        @Override double pay() { return super.pay() + 10_000; }
        @Override public String toString() { return "Manager " + super.toString(); }
    }

    public static void main(String[] args) {
        Employee e = new Manager("Aman");
        System.out.println(e);
        System.out.println(e.pay());
    }
}

